import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {TextDecoder, types} from 'node:util';

export function createDecoder() {
  const utf8 = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true});
  let leading = true;
  let pending = '';
  let data = [];
  let event = '';
  let terminated = false;
  let finished = false;
  let poisoned = false;

  function guard(operation) {
    try {
      if (poisoned || finished) throw new Error('Decoder is closed');
      return operation();
    } catch (error) {
      poisoned = true;
      throw error;
    }
  }

  function processLine(line, frames) {
    if (terminated) {
      if (line !== '') throw new Error('Nonblank line after termination');
      return;
    }
    if (line === '') {
      if (data.length) {
        const value = data.join('\n');
        if (value === '[DONE]') terminated = true;
        else frames.push({event: event || 'message', data: value});
      }
      data = [];
      event = '';
      return;
    }
    if (line.startsWith(':')) return;
    const colon = line.indexOf(':');
    const name = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? '' : line.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (name === 'data') data.push(value);
    else if (name === 'event') event = value;
  }

  function consume(text, frames) {
    if (leading && text.length) {
      leading = false;
      if (text.startsWith('\uFEFF')) text = text.slice(1);
    }
    pending += text;
    let cursor = 0;
    let newline;
    // Each iteration advances past LF, independently of CR stripping.
    while ((newline = pending.indexOf('\n', cursor)) !== -1) {
      let end = newline;
      if (end > cursor && pending[end - 1] === '\r') end--;
      processLine(pending.slice(cursor, end), frames);
      cursor = newline + 1;
    }
    pending = pending.slice(cursor);
  }

  return {
    push(chunk) {
      return guard(() => {
        if (!types.isUint8Array(chunk)) throw new Error('Expected a Uint8Array');
        const frames = [];
        consume(utf8.decode(chunk, {stream: true}), frames);
        return frames;
      });
    },
    finish() {
      return guard(() => {
        consume(utf8.decode(), []);
        if (pending !== '') throw new Error('Unterminated line');
        if (!terminated || data.length || event !== '') {
          throw new Error('Missing termination or pending fields');
        }
        finished = true;
        return [];
      });
    },
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    if (process.argv.length !== 3) throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
    const text = new TextDecoder('utf-8', {fatal: true, ignoreBOM: true})
      .decode(fs.readFileSync(process.argv[2]));
    const input = JSON.parse(text);
    if (input === null || typeof input !== 'object' || Array.isArray(input) ||
        !Array.isArray(input.chunks)) throw new Error('Expected an object with a chunks array');
    const decoder = createDecoder();
    const frames = [];
    for (const encoded of input.chunks) {
      if (typeof encoded !== 'string') throw new Error('Expected base64 string');
      const bytes = Buffer.from(encoded, 'base64');
      if (bytes.toString('base64') !== encoded) throw new Error('Noncanonical base64');
      for (const frame of decoder.push(bytes)) frames.push(frame);
    }
    decoder.finish();
    process.stdout.write(JSON.stringify({frames}) + '\n');
  } catch (error) {
    process.stderr.write(String(error.message) + '\n');
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createDecoder} from '../stream-framer.js';

const done = Buffer.from('data: [DONE]\n\n');
function decode(chunks) {
  const d = createDecoder();
  const frames = chunks.flatMap(chunk => d.push(chunk));
  assert.deepEqual(d.finish(), []);
  return frames;
}

test('whole input, every two-part split, and bytewise input agree with expected values', () => {
  const bytes = Buffer.from('\uFEFFevent: delta\r\ndata: 雪😀\r\ndata: x\ry\r\n\r\ndata: \uFEFF\n\ndata\n\nevent: end\ndata: [DONE]\r\n\r\n\r\n');
  const expected = [
    {event: 'delta', data: '雪😀\nx\ry'},
    {event: 'message', data: '\uFEFF'},
    {event: 'message', data: ''},
  ];
  assert.deepEqual(decode([bytes]), expected);
  for (let split = 0; split <= bytes.length; split++) {
    assert.deepEqual(decode([bytes.subarray(0, split), new Uint8Array(), bytes.subarray(split)]), expected);
  }
  assert.deepEqual(decode(Array.from(bytes, byte => Uint8Array.of(byte))), expected);
});

test('split CRLF, embedded CR, and per-call frame delivery', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(Buffer.from('data: a\r')), []);
  assert.deepEqual(d.push(Buffer.from('\ndata: b\rc\r\r')), []);
  assert.deepEqual(d.push(Buffer.from('\n\r')), []);
  assert.deepEqual(d.push(Buffer.from('\ndata: next\n')), [{event: 'message', data: 'a\nb\rc\r'}]);
  assert.deepEqual(d.push(Buffer.from('\ndata: [DO')), [{event: 'message', data: 'next'}]);
  assert.deepEqual(d.push(Buffer.from('NE]\n')), []);
  assert.deepEqual(d.push(Buffer.from('\n')), []);
  assert.deepEqual(d.finish(), []);
});

test('field parsing preserves values and resets even empty frames', () => {
  const input = 'event: stale\n: comment\nunknown: x\n\n' +
    'data:  leading:colon \nevent: first\nevent: last\n\n' +
    'event: ignored\nevent\ndata\n\n' +
    'Data: no\nEVENT: no\nunknown\n\n' +
    'data:\ndata: \n\n' +
    'data: [DONE] \n\n' +
    'data: [DONE]\ndata: extra\n\n' +
    'data: plain\n\n';
  assert.deepEqual(decode([Buffer.from(input), done]), [
    {event: 'last', data: ' leading:colon '},
    {event: 'message', data: ''},
    {event: 'message', data: '\n'},
    {event: 'message', data: '[DONE] '},
    {event: 'message', data: '[DONE]\nextra'},
    {event: 'message', data: 'plain'},
  ]);
});

test('chunks are not mutated, and typed array bounds are respected', () => {
  const backing = Buffer.concat([Buffer.from('invalid'), done, Buffer.from('invalid')]);
  const copy = Buffer.from(backing);
  const view = new Uint8Array(backing.buffer, backing.byteOffset + 7, done.length);
  assert.deepEqual(decode([view]), []);
  assert.deepEqual(backing, copy);
});

function poisonedAfter(trigger) {
  const d = createDecoder();
  assert.throws(() => trigger(d), Error);
  assert.throws(() => d.push(done), Error);
  assert.throws(() => d.push(new Uint8Array()), Error);
  assert.throws(() => d.finish(), Error);
  assert.deepEqual(decode([done]), []);
}

test('each invalid chunk type poisons only its own decoder', () => {
  for (const value of ['', null, undefined, [], {}, new ArrayBuffer(1), new DataView(new ArrayBuffer(1)), new Uint16Array(1)]) {
    poisonedAfter(d => d.push(value));
  }
});

test('malformed UTF-8 and truncated UTF-8 are fatal and poison', () => {
  for (const bytes of [[0xff], [0x80], [0xc0, 0xaf], [0xed, 0xa0, 0x80], [0xf4, 0x90, 0x80, 0x80], [0xe2, 0x28, 0xa1]]) {
    poisonedAfter(d => d.push(Uint8Array.from(bytes)));
  }
  poisonedAfter(d => {
    d.push(Uint8Array.of(0xe2));
    d.push(Uint8Array.of(0x28));
  });
  for (const bytes of [[0xc2], [0xe2, 0x82], [0xf0, 0x9f, 0x98]]) {
    poisonedAfter(d => {
      d.push(done);
      assert.deepEqual(d.push(Uint8Array.from(bytes)), []);
      d.finish();
    });
  }
});

test('missing termination, pending fields, and final unterminated lines poison', () => {
  for (const input of ['', '\n', ': comment\n', 'data: x\n\n', 'data: [DONE]\n', 'event: x\n', 'event\n', 'data: [DONE]\n\n\r', 'data: [DONE]\n\nx']) {
    poisonedAfter(d => {
      d.push(Buffer.from(input));
      d.finish();
    });
  }
});

test('after termination only blank lines are accepted', () => {
  assert.deepEqual(decode([done, Buffer.from('\n\r\n\n')]), []);
  for (const line of ['data: [DONE]', ': comment', 'unknown', 'event: x', ' ', '\r\r', '\uFEFF']) {
    poisonedAfter(d => {
      d.push(done);
      d.push(Buffer.from(line + '\n'));
    });
  }
});

test('finish is single-use and every push after finish rejects', () => {
  for (const operation of [d => d.finish(), d => d.push(new Uint8Array()), d => d.push(done)]) {
    poisonedAfter(d => {
      d.push(done);
      assert.deepEqual(d.finish(), []);
      operation(d);
    });
  }
});

test('a failed push returns no partial array and leaves earlier values intact', () => {
  const d = createDecoder();
  const earlier = d.push(Buffer.from('data: before\n\n'));
  let result = 'not returned';
  assert.throws(() => { result = d.push(Buffer.from('data: partial\n\ndata: [DONE]\n\n: forbidden\n')); }, Error);
  assert.equal(result, 'not returned');
  assert.deepEqual(earlier, [{event: 'message', data: 'before'}]);
  assert.throws(() => d.finish(), Error);
});

const cli = fileURLToPath(new URL('../stream-framer.js', import.meta.url));
test('CLI validates arguments, files, JSON, base64, protocol, and output atomically', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'stream-framer-'));
  const file = path.join(dir, 'input.json');
  function run(args) {
    const result = spawnSync(process.execPath, [cli, ...args], {encoding: 'utf8'});
    assert.ifError(result.error);
    assert.equal(result.signal, null);
    return result;
  }
  function bad(args) {
    const result = run(args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim().length > 0);
  }
  function badInput(input) {
    fs.writeFileSync(file, JSON.stringify(input));
    bad([file]);
  }
  try {
    const bytes = Buffer.from('data: 雪😀\n\ndata\n\ndata: [DONE]\n\n');
    fs.writeFileSync(file, JSON.stringify({extra: true, chunks: ['', ...Array.from(bytes, byte => Buffer.from([byte]).toString('base64')), '']}));
    const result = run([file]);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify({frames: [{event: 'message', data: '雪😀'}, {event: 'message', data: ''}]}) + '\n');
    bad([]);
    bad([file, 'extra']);
    bad([path.join(dir, 'missing.json')]);
    bad([dir]);
    for (const input of [null, [], 1, 'x', {}, {chunks: null}, {chunks: 'x'}, {chunks: [1]}, {chunks: [null]}, {chunks: []}]) badInput(input);
    for (const encoded of ['Zg', 'Zg=', 'Zg===', ' Zg==', 'Zg==\n', '-w==', '_w==', 'Zh==', 'Zm9=', '====', '!!!!', 'Zg==Zg==']) {
      badInput({chunks: [done.toString('base64'), encoded]});
    }
    for (const bytes of [Buffer.from('data: hello\n\n'), Buffer.from('data: [DONE]\n\n: bad\n'), Buffer.from([0xff])]) {
      badInput({chunks: [bytes.toString('base64')]});
    }
    fs.writeFileSync(file, '{');
    bad([file]);
    fs.writeFileSync(file, Buffer.concat([Buffer.from('{"chunks":[],"extra":"'), Buffer.from([0xff]), Buffer.from('"}')]));
    bad([file]);
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
});

test('import has no CLI side effects', () => {
  const result = spawnSync(process.execPath, ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../stream-framer.js', import.meta.url).href)};`], {encoding: 'utf8'});
  assert.ifError(result.error);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, '');
});

