  const d=createDecoder();
  assert.deepEqual(d.push(Buffer.from('event: delta\ndata: a\ndata: b\n\ndata\n\ndata: [DONE]\n\n')),[
    {event:'delta',data:'a\nb'},{event:'message',data:''}]);
  assert.deepEqual(d.finish(),[]);
});
